begin;
create extension if not exists pg_trgm;
create type public.subscriber_status as enum('active','inactive','suspended','archived');create type public.identity_document_type as enum('dni','passport','other');create type public.connection_status as enum('active','suspended','cancelled','pending');
create table public.organization_sequences(organization_id uuid primary key references organizations(id) on delete cascade,last_subscriber_number integer not null default 0 check(last_subscriber_number between 0 and 999999));
create table public.subscribers(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),code char(6) not null,full_name text not null,normalized_name text not null,whatsapp text not null,email text,address text not null,sector text not null,birth_date date,notes text,status subscriber_status not null default 'active',created_by uuid not null references profiles(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,code));
create table public.subscriber_identities(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),subscriber_id uuid not null references subscribers(id) on delete cascade,document_type identity_document_type not null,issuing_country char(3) not null,document_number text not null,normalized_number text not null,is_primary boolean not null default true,storage_path text,created_by uuid not null references profiles(id),created_at timestamptz not null default now(),unique(organization_id,document_type,issuing_country,normalized_number));
create unique index one_primary_identity_per_subscriber on subscriber_identities(subscriber_id) where is_primary;
create table public.water_connections(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),subscriber_id uuid not null references subscribers(id),code text not null,service_type text not null check(service_type in('residential','commercial','community','institutional')),meter_number text,normalized_meter text,address text not null,sector text not null,installation_date date,latitude numeric(9,6),longitude numeric(9,6),notes text,status connection_status not null default 'active',created_by uuid not null references profiles(id),created_at timestamptz not null default now(),unique(organization_id,code));
create unique index unique_active_meter on water_connections(organization_id,normalized_meter) where normalized_meter is not null and status<>'cancelled';
create table public.duplicate_reviews(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),existing_subscriber_id uuid not null references subscribers(id),new_subscriber_id uuid not null references subscribers(id),similarity_score numeric(5,4) not null,decision text not null check(decision='different_person'),clarification text not null check(length(trim(clarification))>=15),reviewed_by uuid not null references profiles(id),created_at timestamptz not null default now());
create index subscriber_name_trgm on subscribers using gin(normalized_name gin_trgm_ops);create index subscriber_sector_idx on subscribers(organization_id,sector);create index connection_subscriber_idx on water_connections(subscriber_id);
create or replace function public.normalize_person_name(v text) returns text language sql immutable as $$select trim(regexp_replace(upper(translate(coalesce(v,''),'ÁÉÍÓÚÜÑ','AEIOUUN')),'[^A-Z0-9 ]','','g'))$$;
create or replace function public.normalize_identifier(v text) returns text language sql immutable as $$select regexp_replace(upper(coalesce(v,'')),'[^A-Z0-9]','','g')$$;
create or replace function public.mask_identifier(v text) returns text language sql immutable as $$select case when length(normalize_identifier(v))<5 then '****' else left(normalize_identifier(v),4)||'-****-'||right(normalize_identifier(v),4) end$$;
create or replace function public.next_subscriber_code() returns text language plpgsql security definer set search_path=public as $$declare org uuid:=current_organization_id();n integer;begin if not has_permission('subscribers.create') then raise exception 'FORBIDDEN';end if;insert into organization_sequences(organization_id,last_subscriber_number) values(org,1) on conflict(organization_id) do update set last_subscriber_number=organization_sequences.last_subscriber_number+1 returning last_subscriber_number into n;if n>999999 then raise exception 'SEQUENCE_EXHAUSTED';end if;return lpad(n::text,6,'0');end$$;
create or replace function public.check_subscriber_duplicates(p_full_name text,p_document_type text,p_document_number text,p_issuing_country text,p_whatsapp text default null,p_sector text default null) returns table(subscriber_id uuid,subscriber_code text,full_name text,masked_document text,score numeric,match_level text,exact_document boolean) language sql stable security definer set search_path=public as $$with candidates as(select s.id,s.code,s.full_name,i.document_number,(i.document_type::text=p_document_type and i.issuing_country=upper(p_issuing_country) and i.normalized_number=normalize_identifier(p_document_number)) exact_document,greatest(similarity(s.normalized_name,normalize_person_name(p_full_name)),case when regexp_replace(s.whatsapp,'\D','','g')=regexp_replace(coalesce(p_whatsapp,''),'\D','','g') and coalesce(p_whatsapp,'')<>'' then .85 else 0 end,case when lower(s.sector)=lower(coalesce(p_sector,'')) then similarity(s.normalized_name,normalize_person_name(p_full_name))+.05 else 0 end) score from subscribers s join subscriber_identities i on i.subscriber_id=s.id and i.is_primary where s.organization_id=current_organization_id())select id,code,full_name,mask_identifier(document_number),least(score,1),case when exact_document then 'critical' when score>=.85 then 'high' when score>=.70 then 'medium' else 'low' end,exact_document from candidates where exact_document or score>=.60 order by exact_document desc,score desc limit 10$$;
create or replace function public.create_subscriber(p_payload jsonb,p_homonym_note text default null,p_matched_subscriber_id uuid default null) returns uuid language plpgsql security definer set search_path=public as $$declare org uuid:=current_organization_id();sid uuid;code text;matches int;score numeric;begin if not has_permission('subscribers.create') then raise exception 'FORBIDDEN';end if;if auth.jwt()->>'aal'<>'aal2' then raise exception 'MFA_REQUIRED';end if;select count(*) into matches from subscriber_identities where organization_id=org and document_type=(p_payload->>'document_type')::identity_document_type and issuing_country=upper(p_payload->>'issuing_country') and normalized_number=normalize_identifier(p_payload->>'document_number');if matches>0 then raise exception 'DUPLICATE_IDENTITY';end if;if p_matched_subscriber_id is not null then select similarity(normalized_name,normalize_person_name(p_payload->>'full_name')) into score from subscribers where id=p_matched_subscriber_id and organization_id=org;if score>=.70 and length(trim(coalesce(p_homonym_note,'')))<15 then raise exception 'HOMONYM_CLARIFICATION_REQUIRED';end if;end if;code:=next_subscriber_code();insert into subscribers(organization_id,code,full_name,normalized_name,whatsapp,email,address,sector,birth_date,notes,created_by) values(org,code,trim(p_payload->>'full_name'),normalize_person_name(p_payload->>'full_name'),p_payload->>'whatsapp',nullif(p_payload->>'email',''),p_payload->>'address',p_payload->>'sector',nullif(p_payload->>'birth_date','')::date,p_payload->>'notes',auth.uid()) returning id into sid;insert into subscriber_identities(organization_id,subscriber_id,document_type,issuing_country,document_number,normalized_number,created_by) values(org,sid,(p_payload->>'document_type')::identity_document_type,upper(p_payload->>'issuing_country'),p_payload->>'document_number',normalize_identifier(p_payload->>'document_number'),auth.uid());if p_matched_subscriber_id is not null and score>=.70 then insert into duplicate_reviews(organization_id,existing_subscriber_id,new_subscriber_id,similarity_score,decision,clarification,reviewed_by) values(org,p_matched_subscriber_id,sid,score,'different_person',trim(p_homonym_note),auth.uid());end if;perform write_audit_event('create','subscriber',sid::text,null,jsonb_build_object('code',code,'full_name',p_payload->>'full_name'),'Registro de abonado');return sid;exception when unique_violation then raise exception 'DUPLICATE_IDENTITY_OR_CODE';end$$;
create or replace function public.create_water_connection(p_subscriber_id uuid,p_payload jsonb) returns uuid language plpgsql security definer set search_path=public as $$declare org uuid:=current_organization_id();cid uuid;seq int;ccode text;begin if not has_permission('subscribers.update') then raise exception 'FORBIDDEN';end if;if not exists(select 1 from subscribers where id=p_subscriber_id and organization_id=org) then raise exception 'SUBSCRIBER_NOT_FOUND';end if;select count(*)+1 into seq from water_connections where subscriber_id=p_subscriber_id;select code||'-'||lpad(seq::text,2,'0') into ccode from subscribers where id=p_subscriber_id;insert into water_connections(organization_id,subscriber_id,code,service_type,meter_number,normalized_meter,address,sector,installation_date,latitude,longitude,notes,created_by) values(org,p_subscriber_id,ccode,p_payload->>'service_type',nullif(p_payload->>'meter_number',''),nullif(normalize_identifier(p_payload->>'meter_number'),''),p_payload->>'address',p_payload->>'sector',nullif(p_payload->>'installation_date','')::date,nullif(p_payload->>'latitude','')::numeric,nullif(p_payload->>'longitude','')::numeric,p_payload->>'notes',auth.uid()) returning id into cid;perform write_audit_event('create','water_connection',cid::text,null,jsonb_build_object('code',ccode),'Nuevo pegue');return cid;exception when unique_violation then raise exception 'DUPLICATE_ACTIVE_METER';end$$;
create or replace function public.search_subscribers(p_query text default '',p_limit int default 50) returns table(subscriber_id uuid,subscriber_code text,full_name text,masked_document text,sector text,status text) language sql stable security definer set search_path=public as $$select s.id,s.code,s.full_name,mask_identifier(i.document_number),s.sector,s.status::text from subscribers s join subscriber_identities i on i.subscriber_id=s.id and i.is_primary left join water_connections w on w.subscriber_id=s.id where s.organization_id=current_organization_id() and has_permission('subscribers.read') and (coalesce(trim(p_query),'')='' or s.code ilike '%'||p_query||'%' or s.full_name ilike '%'||p_query||'%' or i.normalized_number like '%'||normalize_identifier(p_query)||'%' or s.whatsapp like '%'||p_query||'%' or s.sector ilike '%'||p_query||'%' or w.code ilike '%'||p_query||'%' or w.normalized_meter like '%'||normalize_identifier(p_query)||'%') group by s.id,i.document_number order by s.full_name limit least(p_limit,100)$$;
create or replace function public.get_subscriber_detail(p_subscriber_id uuid) returns jsonb language sql stable security definer set search_path=public as $$select jsonb_build_object('subscriber',to_jsonb(s),'identities',coalesce((select jsonb_agg(to_jsonb(i)||jsonb_build_object('masked_number',mask_identifier(i.document_number))-'document_number'-'normalized_number') from subscriber_identities i where i.subscriber_id=s.id),'[]'::jsonb),'connections',coalesce((select jsonb_agg(to_jsonb(w)) from water_connections w where w.subscriber_id=s.id),'[]'::jsonb)) from subscribers s where s.id=p_subscriber_id and s.organization_id=current_organization_id() and has_permission('subscribers.read')$$;
alter table organization_sequences enable row level security;alter table subscribers enable row level security;alter table subscriber_identities enable row level security;alter table water_connections enable row level security;alter table duplicate_reviews enable row level security;
create policy subscribers_read on subscribers for select using(organization_id=current_organization_id() and has_permission('subscribers.read'));create policy identities_read on subscriber_identities for select using(organization_id=current_organization_id() and has_permission('subscribers.read'));create policy connections_read on water_connections for select using(organization_id=current_organization_id() and has_permission('subscribers.read'));create policy reviews_read on duplicate_reviews for select using(organization_id=current_organization_id() and has_permission('audit.read'));
revoke insert,update,delete on subscribers,subscriber_identities,water_connections,duplicate_reviews,organization_sequences from authenticated;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('subscriber-documents','subscriber-documents',false,10485760,array['image/jpeg','image/png','image/webp','application/pdf']) on conflict(id) do nothing;
create policy subscriber_docs_read on storage.objects for select to authenticated using(bucket_id='subscriber-documents' and (storage.foldername(name))[1]=current_organization_id()::text and has_permission('subscribers.read'));create policy subscriber_docs_write on storage.objects for insert to authenticated with check(bucket_id='subscriber-documents' and (storage.foldername(name))[1]=current_organization_id()::text and has_permission('subscribers.update'));
commit;
